-- =============================
-- transcripts: 실제 전사문 느낌으로 길게
-- chunks: 검색용으로 더 짧고 밀도 높게
-- =============================

INSERT INTO transcripts (transcript_id, session_id, segment_index, start_time, end_time, original_text, created_at) VALUES
('dd110001-0000-0000-0000-000000000001', 'cc110000-0000-0000-0000-000000000001', 0, 0, 200, '오늘은 컴퓨터가 데이터를 어떻게 표현하는지부터 보겠습니다. 우리가 화면에서 보는 글자나 숫자, 이미지도 결국 내부에서는 0과 1의 조합으로 저장됩니다. 비트는 가장 작은 단위이고 여덟 개 비트가 모여 바이트가 됩니다. 문자 하나를 저장하거나 정수를 표현할 때도 이런 이진 표현이 기본이 됩니다.', NOW()),
('dd110001-0000-0000-0000-000000000002', 'cc110000-0000-0000-0000-000000000001', 1, 200, 400, '메모리 구조도 같이 봐야 합니다. RAM은 실행 중인 프로그램이 잠깐 머무는 작업 공간이고 전원이 꺼지면 내용이 사라집니다. 반대로 SSD는 파일을 장기 저장하는 공간입니다. CPU는 메모리에 있는 명령을 읽어 와서 처리하고, 필요한 값은 레지스터 같은 더 빠른 내부 공간에 잠시 저장합니다.', NOW()),
('dd110001-0000-0000-0000-000000000003', 'cc110000-0000-0000-0000-000000000001', 2, 400, 600, '실제로 프로그램이 실행될 때는 명령을 가져오고 해석하고 실행하는 사이클이 반복됩니다. 이 구조를 설명할 때 폰 노이만 구조를 많이 언급합니다. 프로그램과 데이터가 같은 메모리에 저장되기 때문에 구조는 단순하지만, CPU와 메모리 사이의 병목이 생길 수 있다는 점도 함께 기억해야 합니다.', NOW()),

('dd110002-0000-0000-0000-000000000001', 'cc110000-0000-0000-0000-000000000002', 0, 0, 200, '운영체제는 사용자와 하드웨어 사이를 중개하는 핵심 소프트웨어입니다. 프로그램이 실행되면 프로세스라는 단위가 만들어지고, 운영체제는 여러 프로세스가 충돌하지 않도록 자원을 배분합니다. 메모리 관리, 파일 관리, 입출력 관리가 모두 여기 포함됩니다.', NOW()),
('dd110002-0000-0000-0000-000000000002', 'cc110000-0000-0000-0000-000000000002', 1, 200, 400, '프로세스와 스레드는 구분해서 이해해야 합니다. 프로세스는 독립된 실행 단위이고, 스레드는 그 안에서 실제 작업 흐름을 나눈 것입니다. 여러 스레드가 같은 메모리를 공유하면 효율은 올라가지만, 동시에 같은 데이터에 접근할 때 동기화 문제가 생길 수 있습니다.', NOW()),
('dd110002-0000-0000-0000-000000000003', 'cc110000-0000-0000-0000-000000000002', 2, 400, 600, '또 운영체제는 어떤 프로세스에 CPU를 먼저 줄지 결정해야 합니다. 이를 스케줄링이라고 하고, 선입선출이나 라운드 로빈 같은 방식이 있습니다. 자원을 서로 기다리다가 영원히 멈추는 데드락도 중요한 주제입니다. 조건을 하나라도 깨뜨리면 데드락을 예방할 수 있다는 점을 시험에서 자주 묻습니다.', NOW()),

('dd110003-0000-0000-0000-000000000001', 'cc110000-0000-0000-0000-000000000003', 0, 0, 200, '네트워크는 여러 장치가 연결되어 데이터를 주고받는 구조입니다. 가까운 범위를 연결하는 LAN과 넓은 범위를 연결하는 WAN을 구분할 수 있습니다. 인터넷은 전 세계 네트워크가 연결된 거대한 시스템이라고 보면 됩니다.', NOW()),
('dd110003-0000-0000-0000-000000000002', 'cc110000-0000-0000-0000-000000000003', 1, 200, 400, '통신 과정을 설명할 때 OSI 7계층 모델을 자주 사용합니다. 실제 구현에서는 TCP/IP 모델이 더 많이 쓰이지만, 계층별 역할을 이해하는 데는 OSI 모델이 편합니다. IP 주소는 장치를 식별하고, TCP와 UDP는 데이터 전달 방식에서 큰 차이를 보입니다.', NOW()),
('dd110003-0000-0000-0000-000000000003', 'cc110000-0000-0000-0000-000000000003', 2, 400, 600, '웹에서는 HTTP가 기본 통신 규약입니다. 데이터를 단순 조회할 때는 GET, 서버에 전송할 때는 POST를 많이 씁니다. HTTPS는 암호화를 추가한 버전이고, DNS는 사람이 읽는 도메인 이름을 실제 IP 주소로 바꿔 줍니다. 브라우저에서 웹페이지를 여는 과정에 이런 요소가 모두 관여합니다.', NOW()),

('dd220001-0000-0000-0000-000000000001', 'cc220000-0000-0000-0000-000000000001', 0, 0, 200, '경제학은 희소한 자원을 어떻게 배분할지 연구합니다. 자원이 무한하지 않기 때문에 우리는 항상 선택을 해야 하고, 어떤 선택을 하면 다른 선택을 포기하게 됩니다. 그때 포기한 대안의 가치가 기회비용입니다. 단순히 돈만이 아니라 시간과 노동도 기회비용으로 볼 수 있습니다.', NOW()),
('dd220001-0000-0000-0000-000000000002', 'cc220000-0000-0000-0000-000000000001', 1, 200, 400, '수요는 소비자가 각 가격 수준에서 사고 싶어 하는 양이고, 공급은 생산자가 팔고 싶어 하는 양입니다. 보통 가격이 오르면 수요량은 줄고 공급량은 늘어납니다. 그래서 두 곡선이 만나는 지점에서 균형가격이 형성됩니다.', NOW()),
('dd220001-0000-0000-0000-000000000003', 'cc220000-0000-0000-0000-000000000001', 2, 400, 600, '여기서 중요한 것은 수요량의 변화와 수요의 변화를 구분하는 것입니다. 가격 자체가 바뀌어서 같은 곡선 위를 움직이면 수요량의 변화이고, 소득이나 취향처럼 다른 요인 때문에 곡선이 이동하면 수요의 변화입니다. 시험에서는 대체재와 보완재 사례를 자주 줍니다.', NOW()),

('dd220002-0000-0000-0000-000000000001', 'cc220000-0000-0000-0000-000000000002', 0, 0, 200, '탄력성은 어떤 변수 변화에 수요나 공급이 얼마나 민감하게 반응하는지 보여 줍니다. 가격탄력성이 크면 가격이 조금만 변해도 수요량이 크게 움직입니다. 생필품은 대체로 비탄력적이고 사치재는 상대적으로 탄력적인 경우가 많습니다.', NOW()),
('dd220002-0000-0000-0000-000000000002', 'cc220000-0000-0000-0000-000000000002', 1, 200, 400, '정부가 시장에 개입할 때 가격상한제와 가격하한제를 생각할 수 있습니다. 가격상한제를 균형보다 낮게 두면 초과수요가 생기고, 가격하한제를 균형보다 높게 두면 초과공급이 생길 수 있습니다. 임대료 규제나 최저임금 논의가 대표 사례입니다.', NOW()),
('dd220002-0000-0000-0000-000000000003', 'cc220000-0000-0000-0000-000000000002', 2, 400, 600, '세금을 누구에게 부과하느냐와 누가 실제로 부담하느냐는 다를 수 있습니다. 이를 조세의 귀착이라고 합니다. 어느 쪽이 더 비탄력적인지에 따라 실제 부담 비중이 달라지기 때문에, 세금정책을 볼 때는 법적 납부자만 보면 안 됩니다.', NOW()),

('dd220003-0000-0000-0000-000000000001', 'cc220000-0000-0000-0000-000000000003', 0, 0, 200, 'GDP는 일정 기간 한 나라 안에서 생산된 최종 재화와 서비스의 가치를 합한 것입니다. 중간재를 그대로 더하면 이중계산이 되므로 최종 생산물 기준으로 보거나 부가가치만 합산합니다. GDP는 경제 규모를 보여 주는 대표 지표지만 삶의 질 전체를 설명하지는 못합니다.', NOW()),
('dd220003-0000-0000-0000-000000000002', 'cc220000-0000-0000-0000-000000000003', 1, 200, 400, '명목 GDP와 실질 GDP도 구분해야 합니다. 명목 GDP는 해당 연도 가격을 쓰고, 실질 GDP는 기준 연도 가격을 써서 물가 효과를 제거합니다. 성장률을 비교할 때는 실질 GDP가 더 중요합니다. 또 소비자물가지수와 인플레이션 개념도 함께 연결해서 봐야 합니다.', NOW()),
('dd220003-0000-0000-0000-000000000003', 'cc220000-0000-0000-0000-000000000003', 2, 400, 600, '실업률은 일할 의사가 있고 구직 중이지만 일하지 못한 사람의 비율입니다. 마찰적 실업, 구조적 실업, 경기적 실업으로 나누어 설명할 수 있습니다. 물가와 실업의 관계를 다룰 때는 필립스 곡선을 함께 소개하지만, 장기적으로는 단순한 역관계로 보기 어렵다는 비판도 존재합니다.', NOW()),

('dd330001-0000-0000-0000-000000000001', 'cc330000-0000-0000-0000-000000000001', 0, 0, 200, '심리학은 인간의 행동과 정신 과정을 과학적으로 연구합니다. 초기에는 의식을 분석하려는 접근이 강했지만, 이후 행동주의가 등장하면서 관찰 가능한 행동에 초점을 맞추게 됩니다. 다시 인지심리학이 발전하면서 기억, 주의, 문제 해결 같은 내부 과정을 적극적으로 연구하게 되었습니다.', NOW()),
('dd330001-0000-0000-0000-000000000002', 'cc330000-0000-0000-0000-000000000001', 1, 200, 400, '연구방법도 중요합니다. 실험법은 독립변인을 조작해 종속변인의 변화를 보는 방식이고, 관찰법과 조사법은 비교적 자연스러운 자료를 모으는 데 유용합니다. 상관연구는 관계를 찾는 데 좋지만 인과관계를 바로 말할 수는 없습니다.', NOW()),
('dd330001-0000-0000-0000-000000000003', 'cc330000-0000-0000-0000-000000000001', 2, 400, 600, '심리학 연구에서는 윤리 문제가 매우 중요합니다. 참여자 동의, 위험 최소화, 사후 설명이 핵심 원칙입니다. 과거의 유명 실험들은 학문적으로 큰 영향을 주었지만 동시에 연구윤리 기준을 강화하는 계기가 되었습니다.', NOW()),

('dd330002-0000-0000-0000-000000000001', 'cc330000-0000-0000-0000-000000000002', 0, 0, 200, '학습은 경험으로 인해 비교적 지속적인 행동 변화가 일어나는 과정입니다. 고전적 조건형성은 파블로프 실험으로 설명할 수 있고, 중성자극이 반복 결합을 통해 조건자극이 되는 과정을 이해해야 합니다.', NOW()),
('dd330002-0000-0000-0000-000000000002', 'cc330000-0000-0000-0000-000000000002', 1, 200, 400, '조작적 조건형성은 행동의 결과가 이후 행동 빈도에 영향을 준다는 관점입니다. 강화는 행동을 늘리고 처벌은 행동을 줄입니다. 여기서 정적 강화와 부적 강화는 모두 행동을 증가시킨다는 점을 학생들이 자주 헷갈립니다.', NOW()),
('dd330002-0000-0000-0000-000000000003', 'cc330000-0000-0000-0000-000000000002', 2, 400, 600, '반두라의 관찰학습도 중요한 주제입니다. 사람은 직접 강화받지 않아도 다른 사람을 보고 배울 수 있습니다. 보보인형 실험은 모델의 행동이 관찰자에게 어떤 영향을 주는지 보여 주는 대표 사례입니다.', NOW()),

('dd330003-0000-0000-0000-000000000001', 'cc330000-0000-0000-0000-000000000003', 0, 0, 200, '기억은 정보를 부호화하고 저장하고 인출하는 과정입니다. 감각기억, 단기기억, 장기기억으로 구분하는 전통적 모형이 자주 소개됩니다. 단기기억은 용량 제한이 있고, 반복이나 정교화가 장기 저장에 도움을 줍니다.', NOW()),
('dd330003-0000-0000-0000-000000000002', 'cc330000-0000-0000-0000-000000000003', 1, 200, 400, '망각은 단순히 저장 실패만으로 설명되지 않습니다. 시간이 지나면서 약해질 수도 있고, 다른 정보의 간섭 때문에 인출이 어려워질 수도 있습니다. 학습 간격을 나누는 분산학습이 효과적인 이유도 여기와 연결됩니다.', NOW()),
('dd330003-0000-0000-0000-000000000003', 'cc330000-0000-0000-0000-000000000003', 2, 400, 600, '인출 단서와 맥락의 중요성도 강조해야 합니다. 어떤 정보를 배울 때의 환경과 시험 상황이 비슷하면 기억이 더 잘 떠오를 수 있습니다. 또 기존 스키마에 따라 새로운 정보를 해석하는 과정에서 기억 왜곡이 생길 수 있다는 점도 시험에 자주 나옵니다.', NOW());

INSERT INTO chunks (chunk_id, session_id, chunk_index, start_time, end_time, chunk_text, created_at) VALUES
('ee110001-0000-0000-0000-000000000001', 'cc110000-0000-0000-0000-000000000001', 0, 0, 120, '비트는 데이터의 최소 단위이고 8비트는 1바이트다.', NOW()),
('ee110001-0000-0000-0000-000000000002', 'cc110000-0000-0000-0000-000000000001', 1, 120, 240, '컴퓨터 내부 데이터는 0과 1의 이진 표현으로 저장된다.', NOW()),
('ee110001-0000-0000-0000-000000000003', 'cc110000-0000-0000-0000-000000000001', 2, 240, 360, 'RAM은 휘발성 작업 공간이고 SSD는 비휘발성 저장장치다.', NOW()),
('ee110001-0000-0000-0000-000000000004', 'cc110000-0000-0000-0000-000000000001', 3, 360, 480, 'CPU는 명령을 읽고 실행하며 레지스터는 초고속 임시 저장 공간이다.', NOW()),
